'use strict';

let frames = 0;
let offset = 0;

export function applyUserProperties(changed) {
	if (changed.offset !== undefined) offset = changed.offset;
}

export function update(value) {
	frames += 1;
	shared.count = (shared.count || 0) + 1;
	value.x = frames;
	value.y = shared.count;
	value.z = offset;
	return value;
}
